// src/utils/provenance.js
// Where a piece of content came from, in one vocabulary used everywhere it is shown.
//   official   - passed the admin review queue (verified === true). The only content called official.
//   community  - published by another student.
//   student    - the viewer's own content.
//   ai-draft   - generated by AI and not reviewed.
//   unverified - made by RevisionFlow in the past (older bulk-generated sets) but never reviewed by an admin,
//                so it is labelled "Not yet reviewed" until one is.
// Nothing generated by AI is ever "official" until an admin has approved it.

export const PROVENANCE_LABELS = Object.freeze({
  official:   'Official - reviewed',
  community:  'Community',
  student:    'Created by you',
  'ai-draft': 'AI-generated draft',
  unverified: 'Not yet reviewed',
})

export function flashcardSetSource(set, viewerUid = null) {
  if (!set) return 'unverified'
  const claimsOfficial = set.uid === 'official' || set.authorType === 'official' || set.official === true
  if (claimsOfficial) return set.verified === true ? 'official' : 'unverified'
  if (set.origin === 'ai-generated-draft') return 'ai-draft'
  if (viewerUid && set.uid === viewerUid) return 'student'
  return 'community'
}

export const isOfficialSet = (set) => flashcardSetSource(set) === 'official'
// Sets another student made public (never official or unverified-official).
export const isCommunitySet = (set, viewerUid = null) => ['community', 'student'].includes(flashcardSetSource(set, viewerUid))
